  "ui.finalDesignFlow.0e94726136": "代理工具可透過 Composio GitHub 連接器存取；儲存庫網址仍可透過本機 git 或 GitHub CLI 使用。",
  "ui.finalDesignFlow.723772b0a0": "僅當此專案需要透過連接器使用 GitHub 工具時，才新增 Composio API 金鑰。",
  "ui.finalDesignFlow.21f5844795": "當此裝置無法讀取儲存庫時，可使用 Composio GitHub 連接器作為備用方式。",
  "ui.finalDesignFlow.f32b39ae4f": "請完成 Composio 授權視窗中的操作；本機 GitHub 匯入仍可使用。",
  "ui.finalDesignFlow.2a0d6e82a3": "正在背景檢查連接器狀態；不影響透過網址匯入。",
