  "ui.finalOnboarding.f54f5d4bcd": "您的設定",
  "ui.finalOnboarding.7d2d594053": "您想如何使用 Pixflow？",
  "ui.finalOnboarding.bdf73477f9": "連接 API 服務商",
  "ui.finalOnboarding.28edc3b8f2": "連接您的 AI 訂閱",
  "ui.finalOnboarding.f9573d1164": "可以開始創作了",
  "ui.finalOnboarding.45ddd1221b": "WordPress 與 Gutenberg 編輯免費，無需授權或試用。",
  "ui.finalOnboarding.6072f06060": "啟用授權以開始使用。已經啟用？授權將顯示在這裡。",
  "ui.finalOnboarding.ae83bc42b4": "選擇適合您的方式。隨時可在設定中變更。",
  "ui.finalOnboarding.c9e2eb7fcb": "使用服務商提供的 API 金鑰。此方式不需要 Bridge。",
  "ui.finalOnboarding.5add76d77c": "Bridge 將此網站連接至電腦上的 AI 代理。AI 用量由您的服務商帳戶提供。",
  "ui.finalOnboarding.4813d31d25": "無需連接 AI 即可使用 WordPress 工作區。",
  "ui.finalOnboarding.fbcd710247": "連線已設定完成。請提出問題或描述您想建構的內容。",
  "ui.finalOnboarding.24fba6f166": "連接 AI 訂閱",
  "ui.finalOnboarding.82d6b8daef": "透過 Pixflow Design Bridge 使用 Codex、OpenCode 等支援的代理。",
  "ui.finalOnboarding.894f66ba11": "使用 API 金鑰",
  "ui.finalOnboarding.e76c3bfd0e": "直接連接服務商。API 用量另行計費。",
  "ui.finalOnboarding.1be451ef72": "不使用 AI，繼續",
  "ui.finalOnboarding.88e6e83b86": "使用 WordPress 工作區。之後可依需要新增 AI。",
  "ui.finalOnboarding.105e56e56f": "為什麼選擇本機 CLI？",
  "ui.finalOnboarding.5df057fcd7": "API 用量另行計費",
  "ui.finalOnboarding.44e30ed15f": "BYOK 需要 API 金鑰。AI 服務商會在 CLI 訂閱之外另行收取 API 費用，因此這可能產生額外費用，而不是使用 CLI 帳戶包含的額度或每週用量限制。",
  "ui.finalOnboarding.5f9b0ae108": "僅限本次工作階段",
  "ui.finalOnboarding.3c0e1f05da": "僅在此面板工作階段開啟期間保留內容脈絡。重新載入後將重新開始。",
  "ui.finalOnboarding.3efe5537cf": "重新載入後還原",
  "ui.finalOnboarding.1ccaa4f4ad": "在此瀏覽器分頁重新載入後還原限定範圍的內容脈絡。",
  "ui.finalOnboarding.a7f9620cca": "此裝置上",
  "ui.finalOnboarding.94536fb7d6": "在此裝置重新啟動瀏覽器後，仍保留限定範圍的本機內容脈絡。",
