  "ui.mediaStarter.image1.title": "雜誌風格肖像",
  "ui.mediaStarter.image1.tag": "肖像",
  "ui.mediaStarter.image1.prompt": "一位二十多歲後半段的年輕創意總監的雜誌風格特寫肖像。柔和的自然光透過高大的工作室窗戶，使用溫暖的中性色調（奶油色、灰褐色、柔黑色），以 85mm f/1.8 淺景深拍攝，銳利目光直視鏡頭，細微底片顆粒，素顏感。",
  "ui.mediaStarter.image2.title": "產品主視覺",
  "ui.mediaStarter.image2.tag": "電商",
  "ui.mediaStarter.image2.prompt": "一只霧面陶瓷咖啡杯的高級產品主視覺，放在溫暖的奶油色紙質背景上。左上方硬質輪廓光，柔和細長陰影延伸至右下方，杯中升起淡淡蒸汽。正方形裁切，置中構圖，上方留出標題空間，畫面中無道具或手。",
  "ui.mediaStarter.image3.title": "扁平插畫",
  "ui.mediaStarter.image3.tag": "插畫",
  "ui.mediaStarter.image3.prompt": "雨天窗邊舒適閱讀角的扁平向量插畫，使用幾何形狀與克制的五色調色盤（奶油色、陶土色、深青色、焦赭色、柔黑色），以 1.5px 細線點綴，無漸層、無紋理，僅前景扶手椅有柔和陰影。",
  "ui.mediaStarter.video1.title": "產品揭幕",
  "ui.mediaStarter.video1.tag": "電影感",
  "ui.mediaStarter.video1.prompt": "5 秒產品揭幕鏡頭：簡約高級保養品瓶放在乾淨的奶油色石材表面上，鏡頭左側柔和側光，鏡頭緩慢推進，淺景深焦點從瓶蓋輕微轉移至標籤，動作克制，無文字疊加，畫面中無人。",
  "ui.mediaStarter.video2.title": "燈籠特寫",
  "ui.mediaStarter.video2.tag": "氛圍",
  "ui.mediaStarter.video2.prompt": "6 秒電影感特寫：年輕女子在黃金時刻的薄霧松林中捧著發光紙燈籠。淺景深聚焦雙眼，鏡頭輕柔推進，空氣中的微粒漂浮在溫暖光束中，無對白，僅有森林環境聲。",
  "ui.mediaStarter.video3.title": "霓虹街頭甩尾",
  "ui.mediaStarter.video3.tag": "動作",
  "ui.mediaStarter.video3.prompt": "5 秒夜間街頭賽車跟拍，場景是霓虹燈照亮的賽博龐克香港小巷。低角度鏡頭跟隨霧黑色跑車甩尾過急彎，車輪有動態模糊，前方霓虹招牌產生鏡頭光暈，雨水濕潤的柏油路反射燈光，無螢幕文字。",
  "ui.mediaStarter.hyperframes1.title": "放大鏡揭示",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "製作一個 5 秒作品：乾淨畫布上只有一行粗體展示文字。讓圓形放大鏡從左到右移動，經過時透過輕微玻璃折射扭曲下方字母。使用 HyperFrames html-in-canvas 擷取文字 DOM，並透過類似 vfx-liquid-glass 的處理層疊加鏡頭著色器。文字使用純 CSS，玻璃效果為 WebGL 層。",
  "ui.mediaStarter.hyperframes2.title": "CRT 終端機場景",
  "ui.mediaStarter.hyperframes2.tag": "復古特效",
  "ui.mediaStarter.hyperframes2.prompt": "製作 CRT 螢幕作品：深色畫布，等寬終端機文字輸入 `npx hyperframes init my-video`，然後呼叫 `claude` 並使用提示詞 'Add a CRT effect using HTML-in-canvas'。透過 html-in-canvas 在即時 DOM 上疊加輕微凸面曲率著色器、掃描線、少量色差與柔和螢光輝光。終端機文字維持真實 CSS，使其在著色器處理前像素清晰。",
  "ui.mediaStarter.hyperframes3.title": "數位故障崩解",
  "ui.mediaStarter.hyperframes3.tag": "故障效果",
  "ui.mediaStarter.hyperframes3.prompt": "建構 6 秒作品：深色畫布上顯示主標題與一行副標題，然後發生強烈數位故障——RGB 通道分離、水平位移條帶、短暫影格卡頓，最後恢復乾淨畫面。透過 html-in-canvas 擷取即時 DOM 並疊加故障處理層，使著色器下方的文字保持真實 CSS。",
  "ui.mediaStarter.audio1.title": "品牌旁白",
  "ui.mediaStarter.audio1.tag": "語音",
  "ui.mediaStarter.audio1.prompt": "為產品發表影片製作 30 秒溫暖敘事旁白，自信但像交談，語速適中，品牌名稱後短暫停頓。台詞：'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' 使用英語、中性北美口音。",
  "ui.mediaStarter.audio2.title": "入門引導旁白",
  "ui.mediaStarter.audio2.tag": "語音",
  "ui.mediaStarter.audio2.prompt": "為行動應用程式首次啟動畫面製作 20 秒友善引導旁白。語氣安心、帶微笑，語速從容而貼心，不像照本宣科。台詞：「歡迎來到 Loop。讓我們設定您的空間，只需三個簡單問題即可開始。之後您可以隨時變更這些設定。」",
  "ui.mediaStarter.audio3.title": "故事片段朗讀",
  "ui.mediaStarter.audio3.tag": "語音",
  "ui.mediaStarter.audio3.prompt": "用 45 秒以電影感朗讀開篇片段。聲音低沉、節奏從容，句間留有呼吸，帶一點貼近麥克風的親密感。台詞：「這座城市在片刻間沉睡。拉麵櫃檯上方的霓虹招牌閃爍著。街道對面，一扇窗亮著光——午夜這一側唯一還亮著的窗。」",
